import{c as e,Q as d,j as a,m as s}from"./chunks/framework.DxgWTcNC.js";const g=JSON.parse('{"title":"Architecture Quick Reference","description":"","frontmatter":{},"headers":[],"relativePath":"appendix/B-arch-reference.md","filePath":"appendix/B-arch-reference.md","lastUpdated":null}'),r={name:"appendix/B-arch-reference.md"};function n(o,t,i,l,c,p){return d(),a("div",null,[...t[0]||(t[0]=[s(`<h1 id="architecture-quick-reference" tabindex="-1">Architecture Quick Reference <a class="header-anchor" href="#architecture-quick-reference" aria-label="Permalink to &quot;Architecture Quick Reference&quot;">​</a></h1><p>Per-architecture summary of registers, calling conventions, and the disassembly idioms you see most often. Use as a desk reference.</p><h2 id="arm-cortex-m-armv6-m-armv7-m-armv8-m-thumb-only" tabindex="-1">ARM Cortex-M (ARMv6-M / ARMv7-M / ARMv8-M, Thumb only) <a class="header-anchor" href="#arm-cortex-m-armv6-m-armv7-m-armv8-m-thumb-only" aria-label="Permalink to &quot;ARM Cortex-M (ARMv6-M / ARMv7-M / ARMv8-M, Thumb only)&quot;">​</a></h2><p><strong>Registers:</strong></p><table tabindex="0"><thead><tr><th>Reg</th><th>Role</th></tr></thead><tbody><tr><td>r0–r3</td><td>argument registers, return in r0 (and r1 for 64-bit return)</td></tr><tr><td>r4–r11</td><td>callee-saved</td></tr><tr><td>r12 (ip)</td><td>intra-procedure scratch</td></tr><tr><td>r13 (sp)</td><td>stack pointer</td></tr><tr><td>r14 (lr)</td><td>link register (return address)</td></tr><tr><td>r15 (pc)</td><td>program counter</td></tr><tr><td>s0–s31</td><td>single-precision FP (Cortex-M4F has SP-only FPv4-SP)</td></tr><tr><td>d0–d15</td><td>double-precision FP (Cortex-M7 with FPv5-D16 only)</td></tr></tbody></table><p><strong>Calling convention (AAPCS):</strong></p><ul><li>args: r0..r3, then stack</li><li>return: r0 (r0:r1 for 64-bit)</li><li>stack alignment: 8 bytes at function entry</li><li>hard-float: float args in s0..s15</li></ul><p><strong>Common prologue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>push {r4-r7, lr}        ; save callee-saved + lr</span></span>
<span class="line"><span>sub  sp, #N             ; allocate locals</span></span></code></pre></div><p><strong>Common epilogue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>add  sp, #N</span></span>
<span class="line"><span>pop  {r4-r7, pc}        ; restore + return</span></span></code></pre></div><p><strong>Memory map (architecture):</strong></p><table tabindex="0"><thead><tr><th>Range</th><th>Contents</th></tr></thead><tbody><tr><td><code>0x00000000–0x1FFFFFFF</code></td><td>code</td></tr><tr><td><code>0x20000000–0x3FFFFFFF</code></td><td>SRAM</td></tr><tr><td><code>0x40000000–0x5FFFFFFF</code></td><td>peripherals</td></tr><tr><td><code>0x60000000–0x9FFFFFFF</code></td><td>external RAM</td></tr><tr><td><code>0xA0000000–0xDFFFFFFF</code></td><td>external device</td></tr><tr><td><code>0xE0000000–0xE00FFFFF</code></td><td>Private Peripheral Bus (PPB) — SCS (NVIC, SysTick, SCB) sub-range at <code>0xE000E000–0xE000EFFF</code></td></tr><tr><td><code>0xE0100000–0xFFFFFFFF</code></td><td>vendor-specific</td></tr></tbody></table><p><strong>Vector table (first words at flash base):</strong></p><ol><li>Initial SP</li><li>Reset vector</li><li>NMI</li><li>HardFault</li><li>MemManage (M3+)</li><li>BusFault (M3+)</li><li>UsageFault (M3+)</li><li>SecureFault (M33+) / reserved 9-11. reserved</li><li>SVCall</li><li>DebugMon</li><li>reserved</li><li>PendSV</li><li>SysTick 17+. external IRQs (vendor-defined)</li></ol><h2 id="arm-cortex-a-aarch32" tabindex="-1">ARM Cortex-A AArch32 <a class="header-anchor" href="#arm-cortex-a-aarch32" aria-label="Permalink to &quot;ARM Cortex-A AArch32&quot;">​</a></h2><p>Same calling convention as Cortex-M. Adds:</p><ul><li>ARM mode (32-bit instructions) in addition to Thumb</li><li>Coprocessor instructions (<code>MRC</code>, <code>MCR</code>)</li><li>NEON SIMD (q0..q15)</li><li>MMU, FPU as standard</li></ul><h2 id="arm-cortex-a-aarch64" tabindex="-1">ARM Cortex-A AArch64 <a class="header-anchor" href="#arm-cortex-a-aarch64" aria-label="Permalink to &quot;ARM Cortex-A AArch64&quot;">​</a></h2><p><strong>Registers:</strong></p><table tabindex="0"><thead><tr><th>Reg</th><th>Role</th></tr></thead><tbody><tr><td>x0–x7</td><td>arguments, return in x0/x1</td></tr><tr><td>x8</td><td>indirect result location</td></tr><tr><td>x9–x15</td><td>temporary (caller-saved)</td></tr><tr><td>x16–x17</td><td>intra-procedure scratch</td></tr><tr><td>x18</td><td>platform register (sometimes)</td></tr><tr><td>x19–x28</td><td>callee-saved</td></tr><tr><td>x29 (fp)</td><td>frame pointer</td></tr><tr><td>x30 (lr)</td><td>link register</td></tr><tr><td>sp</td><td>stack pointer (separate from x31)</td></tr><tr><td>xzr</td><td>zero register</td></tr><tr><td>v0–v31</td><td>SIMD/FP</td></tr></tbody></table><p><strong>Calling convention (AAPCS64):</strong></p><ul><li>args: x0..x7 integer, v0..v7 FP</li><li>return: x0 (x1 for 128-bit), v0</li><li>stack alignment: 16 bytes</li></ul><p><strong>Common prologue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>stp x29, x30, [sp, #-N]!     ; push fp + lr, allocate frame</span></span>
<span class="line"><span>mov x29, sp                  ; new fp</span></span></code></pre></div><p><strong>Common epilogue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>ldp x29, x30, [sp], #N       ; restore + dealloc</span></span>
<span class="line"><span>ret</span></span></code></pre></div><h2 id="xtensa-lx6-lx7-esp32-family" tabindex="-1">Xtensa LX6/LX7 (ESP32 family) <a class="header-anchor" href="#xtensa-lx6-lx7-esp32-family" aria-label="Permalink to &quot;Xtensa LX6/LX7 (ESP32 family)&quot;">​</a></h2><p><strong>Registers:</strong></p><table tabindex="0"><thead><tr><th>Reg</th><th>Role</th></tr></thead><tbody><tr><td>a0</td><td>return address</td></tr><tr><td>a1 (sp)</td><td>stack pointer</td></tr><tr><td>a2..a7</td><td>arguments (windowed ABI)</td></tr><tr><td>a2..a5</td><td>return values (up to 16 bytes)</td></tr><tr><td>a8..a15</td><td>local temporaries</td></tr><tr><td>(physical)</td><td>up to 64 physical ARs; only 16 visible at once via the window</td></tr></tbody></table><p><strong>Calling convention (windowed):</strong></p><ul><li><code>CALL4/8/12 label</code> slides the window by 4, 8, or 12 registers</li><li>args in a2..a7</li><li>return in a2..a5</li><li><code>RETW</code> returns and slides window back</li></ul><p><strong>Common prologue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>ENTRY a1, N             ; allocate N bytes, slide window</span></span></code></pre></div><p><strong>Common epilogue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>RETW.N</span></span></code></pre></div><p><strong>ESP32 memory map highlights:</strong></p><table tabindex="0"><thead><tr><th>Range</th><th>Region</th></tr></thead><tbody><tr><td><code>0x40000000–0x4005FFFF</code></td><td>ROM</td></tr><tr><td><code>0x40080000–0x4009FFFF</code></td><td>IRAM</td></tr><tr><td><code>0x3FFB0000–0x3FFFFFFF</code></td><td>DRAM</td></tr><tr><td><code>0x400D0000–0x40400000</code></td><td>Flash code (cached)</td></tr><tr><td><code>0x3F400000–0x3F800000</code></td><td>Flash data (cached)</td></tr></tbody></table><h2 id="risc-v-rv32-with-c-extension-esp32-c-bl602-generic" tabindex="-1">RISC-V RV32 (with C extension; ESP32-C, BL602, generic) <a class="header-anchor" href="#risc-v-rv32-with-c-extension-esp32-c-bl602-generic" aria-label="Permalink to &quot;RISC-V RV32 (with C extension; ESP32-C, BL602, generic)&quot;">​</a></h2><p><strong>Register names (ABI):</strong></p><table tabindex="0"><thead><tr><th>ABI</th><th>Reg</th><th>Role</th></tr></thead><tbody><tr><td>zero</td><td>x0</td><td>hardwired 0</td></tr><tr><td>ra</td><td>x1</td><td>return address</td></tr><tr><td>sp</td><td>x2</td><td>stack pointer</td></tr><tr><td>gp</td><td>x3</td><td>global pointer</td></tr><tr><td>tp</td><td>x4</td><td>thread pointer</td></tr><tr><td>t0–t2</td><td>x5–x7</td><td>temporaries (caller-saved)</td></tr><tr><td>s0/fp</td><td>x8</td><td>saved / frame pointer</td></tr><tr><td>s1</td><td>x9</td><td>saved</td></tr><tr><td>a0–a1</td><td>x10–x11</td><td>args / return</td></tr><tr><td>a2–a7</td><td>x12–x17</td><td>args</td></tr><tr><td>s2–s11</td><td>x18–x27</td><td>callee-saved</td></tr><tr><td>t3–t6</td><td>x28–x31</td><td>temporaries</td></tr></tbody></table><p><strong>Calling convention:</strong></p><ul><li>args: a0..a7 (8 args in regs)</li><li>return: a0 (a1 for 64-bit on RV32)</li><li>callee-saved: s0..s11</li><li>stack: 16-byte aligned (typically)</li></ul><p><strong>Common prologue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>addi  sp, sp, -N</span></span>
<span class="line"><span>sw    ra, (N-4)(sp)</span></span>
<span class="line"><span>sw    s0, (N-8)(sp)</span></span>
<span class="line"><span>addi  s0, sp, N</span></span></code></pre></div><p><strong>Common epilogue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>lw    s0, (N-8)(sp)</span></span>
<span class="line"><span>lw    ra, (N-4)(sp)</span></span>
<span class="line"><span>addi  sp, sp, N</span></span>
<span class="line"><span>ret                     ; pseudo for jalr zero, 0(ra)</span></span></code></pre></div><p><strong>Compressed (<code>c</code> ext) prefix on instructions:</strong> <code>c.</code> — half-size encoding of common operations.</p><h2 id="mips32-o32-abi-big-endian-common" tabindex="-1">MIPS32 (O32 ABI, big-endian common) <a class="header-anchor" href="#mips32-o32-abi-big-endian-common" aria-label="Permalink to &quot;MIPS32 (O32 ABI, big-endian common)&quot;">​</a></h2><p><strong>Register names:</strong></p><table tabindex="0"><thead><tr><th>ABI</th><th>Number</th><th>Role</th></tr></thead><tbody><tr><td><code>$zero</code></td><td>0</td><td>hardwired 0</td></tr><tr><td><code>$at</code></td><td>1</td><td>assembler temp</td></tr><tr><td><code>$v0–$v1</code></td><td>2–3</td><td>return values</td></tr><tr><td><code>$a0–$a3</code></td><td>4–7</td><td>args</td></tr><tr><td><code>$t0–$t7</code></td><td>8–15</td><td>temporaries (caller-saved)</td></tr><tr><td><code>$s0–$s7</code></td><td>16–23</td><td>callee-saved</td></tr><tr><td><code>$t8–$t9</code></td><td>24–25</td><td>temporaries; $t9 holds called fn</td></tr><tr><td><code>$k0–$k1</code></td><td>26–27</td><td>kernel-reserved</td></tr><tr><td><code>$gp</code></td><td>28</td><td>global pointer (caller-saved in PIC O32)</td></tr><tr><td><code>$sp</code></td><td>29</td><td>stack pointer</td></tr><tr><td><code>$fp / $s8</code></td><td>30</td><td>frame pointer / saved</td></tr><tr><td><code>$ra</code></td><td>31</td><td>return address</td></tr></tbody></table><p><strong>Calling convention (O32):</strong></p><ul><li>args: $a0..$a3, then stack</li><li>return: $v0 (and $v1 for 64-bit)</li><li>callee-saved: $s0..$s7, $sp, $fp, $ra</li><li><code>$gp</code>: caller-saved in PIC O32, constant in non-PIC code</li><li>first 16 bytes of caller&#39;s stack reserved for arg spill</li></ul><p><strong>Common prologue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>addiu $sp, $sp, -N</span></span>
<span class="line"><span>sw    $ra, (N-4)($sp)</span></span>
<span class="line"><span>sw    $fp, (N-8)($sp)</span></span>
<span class="line"><span>move  $fp, $sp</span></span></code></pre></div><p><strong>Common epilogue:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>move  $sp, $fp</span></span>
<span class="line"><span>lw    $fp, (N-8)($sp)</span></span>
<span class="line"><span>lw    $ra, (N-4)($sp)</span></span>
<span class="line"><span>addiu $sp, $sp, N</span></span>
<span class="line"><span>jr    $ra</span></span>
<span class="line"><span>nop                     ; delay slot</span></span></code></pre></div><p><strong>Branch delay slots</strong> — the instruction after every branch executes before the branch is taken.</p><h2 id="_8051" tabindex="-1">8051 <a class="header-anchor" href="#_8051" aria-label="Permalink to &quot;8051&quot;">​</a></h2><p><strong>Registers:</strong></p><table tabindex="0"><thead><tr><th>Reg</th><th>Role</th></tr></thead><tbody><tr><td>A</td><td>accumulator</td></tr><tr><td>B</td><td>secondary, used by MUL/DIV</td></tr><tr><td>R0–R7</td><td>banked register set (4 banks of 8)</td></tr><tr><td>DPTR</td><td>data pointer (16-bit, often DPL/DPH split)</td></tr><tr><td>SP</td><td>stack pointer (in IDATA)</td></tr><tr><td>PSW</td><td>program status (carry, register bank select, etc.)</td></tr></tbody></table><p><strong>SFRs (special function registers)</strong> at IDATA addresses 0x80–0xFF. Layout chip-specific. Standard SFRs: P0/P1/P2/P3 (ports), TCON/TMOD (timers), SCON/SBUF (UART), IE (interrupt enable), IP (priority).</p><p><strong>Calling convention varies by compiler:</strong></p><ul><li>SDCC: first arg in DPL/DPH for pointer, R7 for char, R7:R6 for int</li><li>Keil C51: args in R7..R3 then memory</li></ul><p><strong>Memory spaces:</strong></p><ul><li>CODE — flash, read-only at runtime</li><li>IDATA — internal RAM (256 bytes max in classic)</li><li>XDATA — external RAM (up to 64 KiB)</li><li>SFR — special function registers (in IDATA upper half)</li><li>BIT — bit-addressable region</li></ul><p><strong>Common access patterns:</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code" tabindex="0"><code><span class="line"><span>MOV A, #imm                   ; load immediate</span></span>
<span class="line"><span>MOVX A, @DPTR                 ; load XDATA</span></span>
<span class="line"><span>MOVC A, @A+DPTR               ; load CODE (table lookup)</span></span>
<span class="line"><span>LCALL addr                    ; long call</span></span>
<span class="line"><span>RET                           ; return</span></span></code></pre></div><h2 id="common-opcode-magic-numbers-first-byte" tabindex="-1">Common opcode magic numbers (first byte) <a class="header-anchor" href="#common-opcode-magic-numbers-first-byte" aria-label="Permalink to &quot;Common opcode magic numbers (first byte)&quot;">​</a></h2><p>For raw byte identification:</p><table tabindex="0"><thead><tr><th>First byte</th><th>Likely meaning</th></tr></thead><tbody><tr><td><code>7F 45 4C 46</code></td><td>ELF</td></tr><tr><td><code>02 00 00 EA</code></td><td>ARM unconditional branch (early ARM image)</td></tr><tr><td><code>27 BD FF E0</code></td><td>MIPS BE <code>addiu $sp, -0x20</code></td></tr><tr><td><code>E0 FF BD 27</code></td><td>MIPS LE same</td></tr><tr><td><code>13 ...</code> or <code>17 ...</code></td><td>RISC-V RV32I uncompressed <code>OP-IMM</code> / <code>AUIPC</code> (low 2 bits = <code>11</code>)</td></tr><tr><td>any byte with low 2 bits <code>00</code>/<code>01</code>/<code>10</code></td><td>RISC-V compressed (RVC)</td></tr><tr><td><code>36 41 00</code></td><td>Xtensa <code>entry a1, 0x20</code> (windowed entry)</td></tr><tr><td><code>02 xx xx</code></td><td>8051 <code>LJMP</code> (vector table start)</td></tr><tr><td><code>E9 xx xx xx xx</code></td><td>x86 32-bit jump</td></tr><tr><td><code>E9</code> (single byte)</td><td>ESP image header magic</td></tr><tr><td><code>1F 8B</code></td><td>gzip</td></tr><tr><td><code>42 5A 68</code></td><td>bzip2</td></tr><tr><td><code>FD 37 7A 58 5A 00</code></td><td>xz</td></tr><tr><td><code>28 B5 2F FD</code></td><td>Zstandard</td></tr><tr><td><code>89 50 4E 47 0D 0A 1A 0A</code></td><td>PNG</td></tr></tbody></table><h2 id="endianness-check-shortcuts" tabindex="-1">Endianness check shortcuts <a class="header-anchor" href="#endianness-check-shortcuts" aria-label="Permalink to &quot;Endianness check shortcuts&quot;">​</a></h2><p>For an unknown blob, decode the first 4 bytes as both endiannesses and check which yields a sensible instruction:</p><ul><li>If big-endian decode is <code>addiu $sp, $sp, -N</code> (MIPS frame allocation): MIPS BE.</li><li>If little-endian decode is the same: MIPS LE.</li><li>If little-endian decode is a Cortex-M <code>push</code> followed by <code>sub sp</code>: Thumb LE.</li><li>If decode looks like nothing in the candidate ISA: try the other endianness, then a different ISA.</li></ul><h2 id="standard-exception-interrupt-vector-ordering" tabindex="-1">Standard exception/interrupt vector ordering <a class="header-anchor" href="#standard-exception-interrupt-vector-ordering" aria-label="Permalink to &quot;Standard exception/interrupt vector ordering&quot;">​</a></h2><p><strong>Cortex-M (first 16 vectors after SP):</strong></p><p>NMI, HardFault, MemManage, BusFault, UsageFault, [reserved×4], SVC, DebugMon, [reserved], PendSV, SysTick.</p><p><strong>RISC-V (CLINT mode):</strong></p><p>A single trap handler (<code>mtvec</code>); software dispatches on <code>mcause</code>.</p><p><strong>RISC-V (vectored mode):</strong></p><p>Trap base + N×4 entries, indexed by <code>mcause</code> low bits (interrupt number).</p><p><strong>MIPS:</strong></p><p>Single exception vector (typically <code>0x80000180</code>); software dispatches on <code>Cause</code> register.</p><p><strong>8051:</strong></p><p>Reset (0x0000), IE0 (0x0003), TF0 (0x000B), IE1 (0x0013), TF1 (0x001B), RI/TI (0x0023), TF2/EXF2 (0x002B). Vendor-extended interrupts at higher addresses.</p>`,85)])])}const u=e(r,[["render",n]]);export{g as __pageData,u as default};
